def ci(c, v=None):
    """Clopper-Pearson 95 % interval as sub/superscript offsets from the point value (per cent), compact enough for ten columns."""
    if v is None:
        return f"[{100 * c[0]:.0f},{100 * c[1]:.0f}]"
    return f"$^{{+{100 * (c[1] - v):.0f}}}_{{-{100 * (v - c[0]):.0f}}}$"


