def strip_review(text):
    """Do not restore review marks already resolved in the canonical manuscript."""
    import re
    pattern = re.compile(r"\\(ClaudeTextOut|ClaudeText|Claude)\{")
    while (m := pattern.search(text)) is not None:
        depth, end = 1, m.end()
        while depth:
            if text[end] == "{" and text[end-1] != "\\": depth += 1
            if text[end] == "}" and text[end-1] != "\\": depth -= 1
            end += 1
        body = text[m.end():end-1] if m.group(1) == "ClaudeText" else ""
        text = text[:m.start()] + body + text[end:]
    return text

